export function runAvailability({busy,wetStarted,complete,plans,approveBlocked=false}){
 const rows=plans.flatMap(p=>p.result?.rows||[]),ready=rows.filter(r=>r.status==='planned').length,blocked=rows.filter(r=>r.status==='blocked').length,skipped=rows.filter(r=>r.status==='skipped').length;
 if(busy)return {enabled:false,loading:wetStarted,message:wetStarted?'RUN מתבצע…':'Dry Run מתבצע. הכפתור ייבדק בסיום.'};
 if(wetStarted)return {enabled:false,loading:false,message:'הריצה הסתיימה או נעצרה. לניסיון נוסף יש לבצע Dry Run חדש.'};
 if(!complete)return {enabled:false,loading:false,message:'יש להשלים Dry Run לקובץ ולמיפוי הנוכחיים לפני RUN.'};
 if(!rows.length)return {enabled:false,loading:false,message:'הקובץ אינו מכיל רשומות לייבוא.'};
 if(!ready)return {enabled:false,loading:false,message:'אין רשומות שניתן לשלוח. '+blocked+' רשומות לא יישלחו; הסיבות והפתרון מוצגים למטה.'};
 if(plans.some(p=>!p.id))return {enabled:false,loading:false,message:'לא התקבל מזהה תוכנית מהשרת. רעננו ובצעו Dry Run מחדש; אם זה חוזר, השרת דורש עדכון.'};
 if(blocked&&!approveBlocked)return {enabled:false,loading:false,message:ready+' רשומות מוכנות · '+blocked+' חסומות. סמנו אישור מפורש לדילוג על החסומות כדי להמשיך.'};
 return {enabled:true,loading:false,message:ready+' רשומות מוכנות ל־RUN'+(skipped?' · '+skipped+' ללא שינוי ידולגו':'')+(blocked?' · '+blocked+' חסומות ידולגו לפי אישורך':'')+'. לחצו להפעלה.'};
}
export function summarizePlans(plans=[]){const rows=new Map();for(const plan of plans){const result=plan.result||{},key=result.sourceEntity||result.targetEntity||result.name||'ישות',summary=rows.get(key)||{key,name:result.name||key,checked:0,create:0,update:0,unchanged:0,created:0,updated:0,failed:0,skipped:0,blocked:0};for(const row of result.rows||[]){summary.checked++;if(row.status==='blocked')summary.blocked++;else if(row.status==='skipped'){summary.unchanged++;summary.skipped++;}else if(row.action==='create')summary.create++;else if(row.action==='update')summary.update++;}rows.set(key,summary);}return [...rows.values()];}
export function summarizeRunRows(rows=[],base=[]){const summaries=new Map(base.map(item=>[item.key,{...item}]));for(const row of rows){const key=row.sourceEntity||row.sourceEntityMeta?.dataName||row.targetEntity||row.entityName||'ישות',summary=summaries.get(key)||{key,name:row.entityName||row.targetEntity||key,checked:0,create:0,update:0,unchanged:0,created:0,updated:0,failed:0,skipped:0,blocked:0};if(row.status==='succeeded'){if(row.action==='create')summary.created++;else summary.updated++;}else if(row.status==='failed')summary.failed++;else if(row.status==='blocked'||row.status==='not_sent')summary.skipped++;summaries.set(key,summary);}return [...summaries.values()];}
