 function batchPlan(mappings){
  if(!fileIndex)return createImportBatches(mappings,importBatchSize);
  const batches=Object.keys(pkg.entities).flatMap((id,index)=>fileIndex.batches[id].map(range=>({
   mapping:mappings[index],range,file:fileIndex.file
  })));
  return {batches,totalRecords:batches.reduce((total,item)=>total+item.range.count,0)};
 }
 const batchRecords=batch=>batch.range?.count??batch.entity.records.length;
 async function readBatch(batch){
  if(!batch.range)return batch;
  const records=await readImportBatch(batch.file,batch.range);
  const {mapping}=batch;
  return {...mapping,entity:{...mapping.entity,meta:{...mapping.entity.meta,recordCount:records.length},records}};
 }
